/* ===== host-http-feedback.js ===== */
(() => {
  const boot = (window.__meiLangBoot = window.__meiLangBoot || {});
  if (boot.hostHttpFeedbackMounted) return;
  boot.hostHttpFeedbackMounted = true;

  const ROOT_ID = "mei-host-http-feedback-root";
  const DEDUPE_MS = 4000;
  const recent = new Map();

  function ensureRoot() {
    let root = document.getElementById(ROOT_ID);
    if (!root) {
      root = document.createElement("div");
      root.id = ROOT_ID;
      root.setAttribute("aria-live", "polite");
      root.setAttribute("aria-relevant", "additions");
      document.body.appendChild(root);
    }
    return root;
  }

  function statusTitle(status) {
    if (status === 401) return "需要登录";
    if (status === 403) return "访问被拒绝";
    if (status === 404) return "资源不存在";
    if (status >= 500) return "服务器错误";
    if (status >= 400) return "请求失败";
    return "HTTP 异常";
  }

  function requestUrlFromInput(input) {
    if (typeof input === "string") return input;
    if (input && typeof input.url === "string") return input.url;
    return "";
  }

  function isSameOriginApiRequest(url) {
    if (!url) return false;
    if (url.startsWith("/")) return url.includes("/api/");
    try {
      const parsed = new URL(url, window.location.origin);
      return (
        parsed.origin === window.location.origin && parsed.pathname.includes("/api/")
      );
    } catch (_) {
      return false;
    }
  }

  function isAuthFlowRequest(url) {
    const value = String(url || "");
    return (
      value.includes("/api/auth/login") ||
      value.includes("/api/auth/public-key") ||
      value.includes("/api/auth/session")
    );
  }

  function redirectToLogin(reason) {
    const auth = window.MeiHostAuthSession;
    if (auth && typeof auth.redirectToLogin === "function") {
      return auth.redirectToLogin(reason);
    }
    const path = window.location.pathname || "";
    if (path === "/login" || path.startsWith("/login/")) return false;
    const next = path + window.location.search + window.location.hash;
    window.location.assign(
      "/login?next=" + encodeURIComponent(next && next !== "/login" ? next : "/"),
    );
    return true;
  }

  async function recoverUnauthorizedRequest(input, init, nativeFetch) {
    const requestUrl = requestUrlFromInput(input);
    if (!isSameOriginApiRequest(requestUrl)) return null;
    if (isAuthFlowRequest(requestUrl) || requestUrl.includes("/api/auth/refresh")) {
      return null;
    }
    const auth = window.MeiHostAuthSession;
    if (!auth || typeof auth.recoverSessionForRequest !== "function") {
      redirectToLogin("session_expired");
      return null;
    }
    const recovered = await auth.recoverSessionForRequest();
    if (!recovered) return null;
    return nativeFetch(input, init);
  }

  function shouldSkipNotify(url, status) {
    if (Number(status) === 401) return true;
    if (!url || !String(url).includes("/api/")) return true;
    if (String(url).includes("/api/host/heartbeat")) return true;
    if (String(url).includes("/api/auth/refresh")) return true;
    if (String(url).includes("/api/agent/")) return true;
    if (String(url).includes("/api/auth/session") && Number(status) === 404) return true;
    if (
      Number(status) === 410 &&
      /\/api\/agent\/session\/[^/?]+\/(diff|revert|unrevert)(?:\?|$)/.test(String(url))
    ) {
      return true;
    }
    const key = String(status) + " " + String(url);
    const now = Date.now();
    const last = recent.get(key) || 0;
    if (now - last < DEDUPE_MS) return true;
    recent.set(key, now);
    return false;
  }

  function parseErrorDetail(text) {
    const raw = String(text || "").trim();
    if (!raw) return "";
    try {
      const payload = JSON.parse(raw);
      if (payload && typeof payload === "object") {
        return String(payload.error || payload.message || "").trim();
      }
    } catch (_) {}
    return raw.length > 240 ? raw.slice(0, 240) + "…" : raw;
  }

  function notify(payload) {
    const status = Number(payload && payload.status) || 0;
    if (!status) return;
    const url = String((payload && payload.url) || "");
    if (shouldSkipNotify(url, status)) return;

    const title = String((payload && payload.title) || statusTitle(status));
    const message = String((payload && payload.message) || "").trim() || "宿主拒绝了本次请求。";
    const tone = status >= 500 || status === 403 || status === 401 ? "error" : "warn";
    const root = ensureRoot();
    const banner = document.createElement("div");
    banner.className =
      "mei-host-http-banner" + (tone === "warn" ? " mei-host-http-banner--warn" : "");
    banner.innerHTML =
      '<div class="mei-host-http-banner__code">HTTP ' +
      String(status) +
      '</div><div class="mei-host-http-banner__body"><div class="mei-host-http-banner__title"></div><div class="mei-host-http-banner__message"></div><div class="mei-host-http-banner__hint"></div></div><button type="button" class="mei-host-http-banner__close" aria-label="关闭">×</button>';
    banner.querySelector(".mei-host-http-banner__title").textContent = title;
    banner.querySelector(".mei-host-http-banner__message").textContent = message;
    banner.querySelector(".mei-host-http-banner__hint").textContent =
      "请向管理员反馈错误代码 HTTP " + String(status) + "。";
    banner.querySelector(".mei-host-http-banner__close").addEventListener("click", () => {
      banner.remove();
    });
    root.prepend(banner);
    window.setTimeout(() => {
      if (banner.isConnected) banner.remove();
    }, 12000);
  }

  const nativeFetch = window.fetch.bind(window);
  window.fetch = async function meiHostFetch(input, init) {
    let response = await nativeFetch(input, init);
    const requestUrl = requestUrlFromInput(input);
    if (
      response.status === 401 &&
      isSameOriginApiRequest(requestUrl) &&
      !isAuthFlowRequest(requestUrl)
    ) {
      const retried = await recoverUnauthorizedRequest(
        input,
        init,
        nativeFetch,
      );
      if (retried) {
        response = retried;
      } else {
        redirectToLogin("session_expired");
      }
    }
    try {
      if (
        requestUrl &&
        (requestUrl.startsWith("/") || requestUrl.startsWith(window.location.origin)) &&
        requestUrl.includes("/api/")
      ) {
        if (!response.ok) {
          let detail = "";
          try {
            detail = parseErrorDetail(await response.clone().text());
          } catch (_) {}
          notify({
            status: response.status,
            url: requestUrl,
            message: detail || response.statusText || "请求失败",
          });
        }
      }
    } catch (_) {}
    return response;
  };

  window.MeiHostHttpFeedback = { notify, statusTitle };
  boot.notifyHostHttpError = notify;
})();


/* ===== host-auth-session.js ===== */
/**
 * 宿主登录态滑动续期：在 JWT 到期前静默调用 POST /api/auth/refresh。
 * 挂载 `window.MeiHostAuthSession`，在所有 --auth 已登录页面 bundle 中紧随 host-http-feedback.js 加载。
 */
(function () {
  if (window.MeiHostAuthSession) return;

  const DEFAULT_REFRESH_LEAD_MS = 30 * 60 * 1000;
  const MIN_REFRESH_DELAY_MS = 5000;

  let refreshTimerId = 0;
  let refreshInFlight = false;
  let redirectInFlight = false;
  let lastSessionPayload = null;

  function readMeta(name) {
    const node = document.querySelector('meta[name="' + name + '"]');
    return node ? String(node.getAttribute("content") || "").trim() : "";
  }

  function readHostCapabilities() {
    const raw =
      document.body?.dataset?.meiAuthCapabilities ||
      readMeta("mei-auth-capabilities") ||
      "{}";
    try {
      const parsed = JSON.parse(raw);
      return parsed && typeof parsed === "object" ? parsed : {};
    } catch (_) {
      return {};
    }
  }

  function isAuthDisabledProfile(caps) {
    return Boolean(
      caps &&
        caps.access_view &&
        caps.config_upload &&
        caps.build_view &&
        caps.access_agent &&
        caps.agent_control &&
        caps.authoring_agent,
    );
  }

  function isLoggedIn() {
    const fromBody = String(document.body?.dataset?.meiAuthLoggedIn || "").trim();
    if (fromBody) return fromBody === "1";
    return readMeta("mei-auth-logged-in") === "1";
  }

  function shouldStart() {
    if (!isLoggedIn()) return false;
    return !isAuthDisabledProfile(readHostCapabilities());
  }

  function isLoginPath(pathname) {
    const path = String(pathname || window.location.pathname || "");
    return path === "/login" || path.startsWith("/login/");
  }

  function redirectToLogin(reason) {
    if (redirectInFlight || isLoginPath()) return false;
    redirectInFlight = true;
    clearRefreshTimer();
    const next =
      window.location.pathname + window.location.search + window.location.hash;
    const target =
      "/login?next=" +
      encodeURIComponent(next && next !== "/login" ? next : "/");
    if (reason) {
      try {
        sessionStorage.setItem("mei_auth_redirect_reason", String(reason));
      } catch (_) {}
    }
    window.location.assign(target);
    return true;
  }

  function clearRefreshTimer() {
    if (refreshTimerId) {
      clearTimeout(refreshTimerId);
      refreshTimerId = 0;
    }
  }

  function refreshLeadMs(payload) {
    const fromPayload = Number(payload && payload.refreshLeadSeconds);
    if (Number.isFinite(fromPayload) && fromPayload > 0) {
      return fromPayload * 1000;
    }
    return DEFAULT_REFRESH_LEAD_MS;
  }

  function dispatchSessionRefreshed(payload) {
    try {
      document.dispatchEvent(
        new CustomEvent("mei:auth-session-refreshed", {
          detail: payload && typeof payload === "object" ? payload : {},
        }),
      );
    } catch (_) {}
  }

  function dispatchSessionExpired(reason) {
    try {
      document.dispatchEvent(
        new CustomEvent("mei:auth-session-expired", {
          detail: { reason: String(reason || "session_expired") },
        }),
      );
    } catch (_) {}
  }

  function handleSessionLost(reason) {
    dispatchSessionExpired(reason);
    redirectToLogin(reason);
  }

  function scheduleRefreshFromPayload(payload) {
    clearRefreshTimer();
    if (!payload || !payload.authenticated || !payload.expiresAt) {
      return;
    }
    const expMs = Number(payload.expiresAt) * 1000;
    if (!Number.isFinite(expMs) || expMs <= 0) return;
    const leadMs = refreshLeadMs(payload);
    const delayMs = expMs - Date.now() - leadMs;
    if (delayMs <= 0) {
      refreshSession("lead_elapsed").catch(function () {});
      return;
    }
    refreshTimerId = setTimeout(function () {
      refreshTimerId = 0;
      refreshSession("scheduled").catch(function () {});
    }, Math.max(MIN_REFRESH_DELAY_MS, delayMs));
  }

  async function fetchSession() {
    const response = await fetch("/api/auth/session", { credentials: "same-origin" });
    if (!response.ok) {
      throw new Error("session check failed: " + response.status);
    }
    return response.json();
  }

  async function refreshSession(_reason) {
    if (refreshInFlight) return lastSessionPayload;
    refreshInFlight = true;
    try {
      const response = await fetch("/api/auth/refresh", {
        method: "POST",
        credentials: "same-origin",
        headers: { "content-type": "application/json" },
      });
      if (response.status === 401) {
        handleSessionLost("session_expired");
        throw new Error("session refresh unauthorized");
      }
      if (!response.ok) {
        throw new Error("session refresh failed: " + response.status);
      }
      const payload = await response.json();
      const sessionPayload = {
        enabled: true,
        authenticated: true,
        expiresAt: payload.expiresAt,
        jwtTtlSeconds: payload.jwtTtlSeconds,
        refreshLeadSeconds: payload.refreshLeadSeconds,
        user: payload.user || null,
      };
      lastSessionPayload = sessionPayload;
      scheduleRefreshFromPayload(sessionPayload);
      dispatchSessionRefreshed(sessionPayload);
      return sessionPayload;
    } finally {
      refreshInFlight = false;
    }
  }

  async function recoverSessionForRequest() {
    if (!shouldStart()) return false;
    try {
      const payload = await refreshSession("fetch_recovery");
      return !!(payload && payload.authenticated);
    } catch (_) {
      return false;
    }
  }

  async function bootstrap() {
    if (!shouldStart()) return;
    try {
      const payload = await fetchSession();
      lastSessionPayload = payload;
      if (!(payload && payload.authenticated)) {
        handleSessionLost("session_expired");
        return;
      }
      scheduleRefreshFromPayload(payload);
    } catch (_) {}
  }

  function onVisibilityChange() {
    if (document.visibilityState !== "visible") return;
    if (!shouldStart()) return;
    const payload = lastSessionPayload;
    if (!payload || !payload.authenticated || !payload.expiresAt) {
      bootstrap().catch(function () {});
      return;
    }
    const expMs = Number(payload.expiresAt) * 1000;
    if (Number.isFinite(expMs) && expMs > 0 && Date.now() >= expMs) {
      handleSessionLost("session_expired");
      return;
    }
    const leadMs = refreshLeadMs(payload);
    const refreshAtMs = expMs - leadMs;
    if (Date.now() >= refreshAtMs) {
      refreshSession("visibility").catch(function () {});
    }
  }

  document.addEventListener("visibilitychange", onVisibilityChange);

  window.MeiHostAuthSession = {
    bootstrap: bootstrap,
    refreshSession: refreshSession,
    recoverSessionForRequest: recoverSessionForRequest,
    redirectToLogin: redirectToLogin,
    scheduleRefreshFromPayload: scheduleRefreshFromPayload,
    getLastSessionPayload: function () {
      return lastSessionPayload;
    },
    dispose: function () {
      clearRefreshTimer();
      document.removeEventListener("visibilitychange", onVisibilityChange);
    },
  };

  bootstrap().catch(function () {});
})();


/* ===== host-heartbeat.js ===== */
/**
 * 宿主心跳：轮询 /api/host/heartbeat，在服务端失联或版本变更时提示用户刷新。
 */
(() => {
  const boot = (window.__meiLangBoot = window.__meiLangBoot || {});
  if (boot.hostHeartbeatMounted) return;
  boot.hostHeartbeatMounted = true;

  const ROOT_ID = "mei-host-heartbeat-root";
  const HEARTBEAT_URL = "/api/host/heartbeat";
  const POLL_MS = 30000;
  const POLL_FAST_MS = 8000;
  const DISCONNECT_AFTER_STREAK = 2;
  const SUCCESS_VISIBLE_MS = 5000;

  let timerId = 0;
  let failureStreak = 0;
  let alertKind = "";
  let remoteVersion = "";
  let probeInFlight = false;
  let lastHeartbeat = null;
  let successTimerId = 0;

  function readMeta(name) {
    const node = document.querySelector('meta[name="' + name + '"]');
    return node ? String(node.getAttribute("content") || "").trim() : "";
  }

  function pageBuildVersion() {
    return readMeta("mei-host-version");
  }

  function formatDurationMs(value) {
    if (value == null || value === "") return "";
    const ms = Number(value);
    if (!Number.isFinite(ms) || ms < 0) return "";
    if (ms < 1000) return Math.round(ms) + "ms";
    if (ms < 60000) return (ms / 1000).toFixed(1) + "s";
    const minutes = Math.floor(ms / 60000);
    const seconds = ((ms % 60000) / 1000).toFixed(1);
    return `${minutes}m ${seconds}s`;
  }

  function heartbeatPhaseLabel(phase) {
    const normalized = String(phase || "").trim().toLowerCase();
    const map = {
      starting: "启动中",
      bound: "已绑定，等待后台构建",
      building: "后台构建中",
      verifying: "校验中",
      degraded: "部分产物未就绪",
      failed: "后台构建失败",
      ready: "已就绪",
      skipped: "已跳过",
    };
    return map[normalized] || normalized || "未知状态";
  }

  function buildAlertCopy(payload) {
    const phase = String(payload?.phase || "").trim().toLowerCase();
    const activeJob = String(payload?.activeJob || "").trim();
    const activeElapsed = formatDurationMs(payload?.activeJobElapsedMs);
    const lastTotal = formatDurationMs(payload?.lastBuildTotalMs);
    const lastCompile = formatDurationMs(payload?.lastBuildCompileMs);
    const lastWarmup = formatDurationMs(payload?.lastBuildWarmupMs);
    const warningCount = Number(payload?.lastWarningCount || 0);
    const title =
      phase === "failed"
        ? "访问态构建失败"
        : phase === "degraded"
          ? "部分访问能力降级"
          : "访问态构建中";
    const lines = [
      `当前状态：${heartbeatPhaseLabel(phase)}`,
      activeJob ? `后台任务：${activeJob}` : "",
      activeElapsed ? `已耗时：${activeElapsed}` : "",
      lastTotal
        ? `最近一次构建：总计 ${lastTotal}${
            lastCompile ? `，编译 ${lastCompile}` : ""
          }${lastWarmup ? `，warmup ${lastWarmup}` : ""}`
        : "",
      warningCount > 0 ? `最近一次构建含 ${warningCount} 条 warning / 降级项。` : "",
      phase === "failed"
        ? "宿主已启动，但部分访问态产物构建失败；请到构建视图检查失败项。"
        : phase === "degraded"
          ? "宿主服务可用；部分页面或指标可能局部降级，未命中缺失产物的功能仍可正常访问。"
          : "宿主已启动，后台正在生成访问态产物；完成前部分页面或指标可能暂时不可用。",
    ].filter(Boolean);
    return { title, message: lines.join(" ") };
  }

  function buildSuccessCopy(payload) {
    const lastTotal = formatDurationMs(payload?.lastBuildTotalMs);
    const lastCompile = formatDurationMs(payload?.lastBuildCompileMs);
    const lastWarmup = formatDurationMs(payload?.lastBuildWarmupMs);
    const fullWarmupReady = payload?.fullWarmupReady === true;
    const message = [
      fullWarmupReady
        ? "OK! 全量访问态产物已就绪，现在可以正常访问页面。"
        : "OK! 关键访问态产物已就绪，后台仍在生成 deferred 产物。",
      lastTotal
        ? `最近一次构建：总计 ${lastTotal}${
            lastCompile ? `，编译 ${lastCompile}` : ""
          }${lastWarmup ? `，warmup ${lastWarmup}` : ""}`
        : "",
    ]
      .filter(Boolean)
      .join(" ");
    return {
      title: fullWarmupReady ? "FULL READY! 全量预热完成" : "ACCESS READY! 访问态已就绪",
      message,
    };
  }

  function shouldRun() {
    if (document.body && document.body.dataset.meiCompileShell === "true") {
      return false;
    }
    if (pageBuildVersion()) return true;
    const path = window.location.pathname || "";
    return (
      path === "/host" ||
      path === "/login" ||
      path.startsWith("/account/") ||
      path.startsWith("/logout")
    );
  }

  function currentPageAppId() {
    const fromRuntime = String(window.__meiRuntimeAppId || "").trim();
    if (fromRuntime) return fromRuntime;
    const match = String(window.location.pathname || "").match(
      /^\/apps\/[^/]+\/([^/]+)/,
    );
    return match ? String(match[1] || "").trim() : "";
  }

  function isShellSurface() {
    const path = window.location.pathname || "";
    return (
      path === "/host" ||
      path === "/login" ||
      path.startsWith("/account/") ||
      path.startsWith("/logout")
    );
  }

  function appAccessReadyFromPayload(payload, appId) {
    if (!payload || !appId) return false;
    const apps = Array.isArray(payload.apps) ? payload.apps : [];
    const entry = apps.find((app) => String(app?.appId || "").trim() === appId);
    if (entry) return entry.accessReady === true;
    return false;
  }

  function ensureRoot() {
    let root = document.getElementById(ROOT_ID);
    if (!root) {
      root = document.createElement("div");
      root.id = ROOT_ID;
      root.setAttribute("aria-live", "assertive");
      root.setAttribute("aria-relevant", "additions");
      document.body.appendChild(root);
    }
    return root;
  }

  function clearBanner() {
    const root = document.getElementById(ROOT_ID);
    if (root) root.innerHTML = "";
  }

  function cancelSuccessTimer() {
    if (successTimerId) {
      clearTimeout(successTimerId);
      successTimerId = 0;
    }
  }

  function renderBanner(kind, payload) {
    const root = ensureRoot();
    const pageVersion = pageBuildVersion();
    const isVersion = kind === "version";
    const isBuild = kind === "build";
    const isSuccess = kind === "success";
    const title = isVersion
      ? "服务端已更新"
      : isSuccess
        ? buildSuccessCopy(payload).title
      : isBuild
        ? buildAlertCopy(payload).title
        : "服务端失联";
    const message = isVersion
      ? "当前页面版本为 " +
        (pageVersion || "未知") +
        "，服务端版本为 " +
        (remoteVersion || "未知") +
        "。请刷新页面以加载新版本。"
      : isSuccess
        ? buildSuccessCopy(payload).message
      : isBuild
        ? buildAlertCopy(payload).message
        : "无法连接宿主服务，请检查网络或联系管理员后刷新页面。";
    const toneClass = isVersion
      ? " mei-host-heartbeat-banner--version"
      : isSuccess
        ? " mei-host-heartbeat-banner--success"
      : " mei-host-heartbeat-banner--offline";

    root.innerHTML =
      '<div class="mei-host-heartbeat-banner' +
      toneClass +
      '" role="alert">' +
      '<div class="mei-host-heartbeat-banner__icon" aria-hidden="true">' +
      (isVersion ? "↑" : isSuccess ? "OK" : "!") +
      '</div><div class="mei-host-heartbeat-banner__body">' +
      '<div class="mei-host-heartbeat-banner__title"></div>' +
      '<div class="mei-host-heartbeat-banner__message"></div>' +
      '<div class="mei-host-heartbeat-banner__actions">' +
      '<button type="button" class="mei-host-heartbeat-banner__btn mei-host-heartbeat-banner__btn--primary" data-action="reload">刷新页面</button>' +
      (isVersion || isSuccess
        ? ""
        : '<button type="button" class="mei-host-heartbeat-banner__btn" data-action="retry">重试连接</button>') +
      "</div></div></div>";

    const banner = root.querySelector(".mei-host-heartbeat-banner");
    banner.querySelector(".mei-host-heartbeat-banner__title").textContent = title;
    banner.querySelector(".mei-host-heartbeat-banner__message").textContent = message;
    banner.querySelector('[data-action="reload"]').addEventListener("click", () => {
      window.location.reload();
    });
    const retry = banner.querySelector('[data-action="retry"]');
    if (retry) {
      retry.addEventListener("click", () => {
        tick();
      });
    }
  }

  function setAlert(kind) {
    if (alertKind === kind) return;
    cancelSuccessTimer();
    alertKind = kind;
    if (!kind) {
      clearBanner();
      return;
    }
    renderBanner(kind, lastHeartbeat);
    if (kind === "success") {
      successTimerId = window.setTimeout(() => {
        successTimerId = 0;
        if (alertKind === "success") {
          setAlert("");
        }
      }, SUCCESS_VISIBLE_MS);
    }
    try {
      document.dispatchEvent(
        new CustomEvent("mei:host-heartbeat-alert", {
          detail: { kind, remoteVersion, pageVersion: pageBuildVersion(), payload: lastHeartbeat },
        }),
      );
    } catch (_) {}
  }

  function scheduleNext() {
    if (timerId) clearTimeout(timerId);
    const delay = alertKind === "offline" || alertKind === "build" ? POLL_FAST_MS : POLL_MS;
    timerId = window.setTimeout(tick, delay);
  }

  function isActivelyBuilding(payload) {
    const phase = String(payload?.phase || "").trim().toLowerCase();
    const activeJob = String(payload?.activeJob || "").trim();
    return (
      activeJob &&
      (phase === "building" || phase === "verifying" || phase === "starting")
    );
  }

  function isHostServiceable(payload) {
    return payload?.hostReady === true || payload?.ready === true;
  }

  function isAccessFullyReady(payload) {
    if (isShellSurface()) {
      return isHostServiceable(payload);
    }
    const appId = currentPageAppId();
    if (appId) {
      return appAccessReadyFromPayload(payload, appId);
    }
    return payload?.accessReady === true || payload?.anyAppAccessReady === true;
  }

  async function tick() {
    if (!shouldRun() || probeInFlight) return;
    probeInFlight = true;
    try {
      const response = await fetch(HEARTBEAT_URL, {
        method: "GET",
        cache: "no-store",
        credentials: "same-origin",
        headers: { accept: "application/json" },
      });
      if (!response.ok) {
        throw new Error("heartbeat status " + String(response.status));
      }
      const payload = await response.json();
      lastHeartbeat = payload && typeof payload === "object" ? payload : null;
      const nextVersion = String((payload && payload.buildVersion) || "").trim();
      remoteVersion = nextVersion;
      failureStreak = 0;

      const pageVersion = pageBuildVersion();
      if (pageVersion && nextVersion && pageVersion !== nextVersion) {
        setAlert("version");
        return;
      }
      if (!isHostServiceable(payload)) {
        if (alertKind === "build") {
          renderBanner("build", lastHeartbeat);
        } else {
          setAlert("build");
        }
        return;
      }
      if (
        !isShellSurface() &&
        !isAccessFullyReady(payload) &&
        isActivelyBuilding(payload)
      ) {
        if (alertKind === "build") {
          renderBanner("build", lastHeartbeat);
        } else {
          setAlert("build");
        }
        return;
      }
      if (isAccessFullyReady(payload) && alertKind === "build") {
        setAlert("success");
        return;
      }
      if (alertKind === "build") {
        setAlert("");
        return;
      }
      if (alertKind === "offline") {
        setAlert("");
      }
    } catch (_) {
      failureStreak += 1;
      if (failureStreak >= DISCONNECT_AFTER_STREAK) {
        setAlert("offline");
      }
    } finally {
      probeInFlight = false;
      if (shouldRun()) scheduleNext();
    }
  }

  function stop() {
    if (timerId) {
      clearTimeout(timerId);
      timerId = 0;
    }
    boot.hostHeartbeatMounted = false;
  }

  function start() {
    if (!shouldRun()) return;
    tick();
    document.addEventListener("visibilitychange", onVisibilityChange);
  }

  function onVisibilityChange() {
    if (document.visibilityState === "visible" && shouldRun()) {
      tick();
    }
  }

  boot.disposeHostHeartbeat = function () {
    document.removeEventListener("visibilitychange", onVisibilityChange);
    stop();
    clearBanner();
  };

  window.MeiHostHeartbeat = {
    tick,
    getAlertKind: () => alertKind,
  };

  start();
})();


/* ===== statusbar.js ===== */
(() => {
  const boot = (window.__meiLangBoot = window.__meiLangBoot || {});
  if (boot.statusBarMounted) return;
  boot.statusBarMounted = true;

  function readMeta(name) {
    const node = document.querySelector('meta[name="' + name + '"]');
    return node ? String(node.getAttribute("content") || "").trim() : "";
  }

  function els() {
    return {
      compliance: document.getElementById("mei-status-compliance"),
      hostVersion: document.getElementById("mei-status-host-version"),
    };
  }

  function setChip(node, text, tone, title) {
    if (!node) return;
    node.textContent = text;
    node.title = title || text;
    node.dataset.tone = tone || "neutral";
  }

  function applyComplianceChip() {
    const nodes = els();
    if (!nodes.compliance) return;
    const parts = [
      readMeta("mei-host-icp-record"),
      readMeta("mei-host-psb-record"),
      readMeta("mei-host-copyright"),
    ].filter(Boolean);
    if (!parts.length) {
      nodes.compliance.hidden = true;
      nodes.compliance.textContent = "";
      return;
    }
    nodes.compliance.hidden = false;
    const text = parts.join(" · ");
    setChip(nodes.compliance, text, "neutral", text);
  }

  function applyHostVersionChip() {
    const nodes = els();
    const label = readMeta("mei-host-version-label");
    const version = readMeta("mei-host-version");
    const text = label || (version ? "Mei " + version : "");
    if (!text) return;
    setChip(nodes.hostVersion, text, "neutral", text);
  }

  function start() {
    applyComplianceChip();
    applyHostVersionChip();
  }

  boot.disposeStatusBar = function () {
    boot.statusBarMounted = false;
  };
  start();
})();


/* ===== manage-ops-panel/p1.js ===== */
(function initManageOpsPanel() {
  const OPS_CONFIG_TARGET = ".mei-config.json";
  let summaryRoot = null;
  let editorRoot = null;

  const state = {
    appId: "",
    journalRevision: 0,
    boundary: null,
    ops: normalizeOps({}),
    journal: { entries: [] },
    selectedPanel: "params",
    selectedSourceId: null,
    paramRows: [],
    paramRowSeq: 0,
    summaryText: "",
    basemapsText: "{}",
    themesText: "{}",
    rawOpsText: "{}",
    rawOpsDirty: false,
    isDirty: false,
    busy: false,
  };

  function resolveRoots() {
    summaryRoot = document.getElementById("manage-ops-summary");
    editorRoot = document.getElementById("manage-ops-editor-root");
    const appId = editorRoot?.dataset.appId || summaryRoot?.dataset.appId || "";
    if (appId) {
      state.appId = appId;
    }
    return !!state.appId && (!!summaryRoot || !!editorRoot);
  }

  function normalizeOps(ops) {
    return {
      params: isPlainObject(ops?.params) ? { ...ops.params } : {},
      basemaps: isPlainObject(ops?.basemaps) ? { ...ops.basemaps } : {},
      themes: isPlainObject(ops?.themes) ? { ...ops.themes } : {},
      sources: isPlainObject(ops?.sources) ? { ...ops.sources } : {},
    };
  }

  function isPlainObject(value) {
    return !!value && typeof value === "object" && !Array.isArray(value);
  }

  function escapeHtml(text) {
    return String(text || "")
      .replaceAll("&", "&amp;")
      .replaceAll("<", "&lt;")
      .replaceAll(">", "&gt;");
  }

  function encodeFileTarget(target) {
    return encodeURIComponent(target).replaceAll("%2F", "/");
  }

  function editorHref() {
    return `/apps/config/${state.appId}`;
  }

  function availableSourceIds() {
    return Object.keys(state.ops.sources).sort();
  }

  function formatTimestamp(value) {
    const ms = Number(value || 0);
    if (!Number.isFinite(ms) || ms <= 0) return "未知时间";
    try {
      return new Date(ms).toLocaleString("zh-CN", {
        hour12: false,
        month: "2-digit",
        day: "2-digit",
        hour: "2-digit",
        minute: "2-digit",
      });
    } catch (_error) {
      return "未知时间";
    }
  }

  function stringifyJson(value) {
    return JSON.stringify(value ?? {}, null, 2);
  }

  function stringifyParamValue(value) {
    if (typeof value === "string") return value;
    return JSON.stringify(value);
  }

  function nextParamRowId() {
    state.paramRowSeq += 1;
    return `param-${state.paramRowSeq}`;
  }

  function hydrateParamRows(params) {
    return Object.entries(params || {}).map(([key, value]) => ({
      id: nextParamRowId(),
      key,
      valueText: stringifyParamValue(value),
    }));
  }

  function formatCountLabel(label, count) {
    return `${label} ${Number(count || 0)}`;
  }

  function sourcePanelKey(id) {
    return `source:${id}`;
  }

  function isSourcePanel(panel) {
    return String(panel || "").startsWith("source:");
  }

  function panelSourceId(panel) {
    return isSourcePanel(panel) ? String(panel).slice("source:".length) : null;
  }

  function ensureSelectedSource() {
    const ids = availableSourceIds();
    if (!ids.length) {
      state.selectedSourceId = null;
      return;
    }
    if (!state.selectedSourceId || !state.ops.sources[state.selectedSourceId]) {
      state.selectedSourceId = ids[0];
    }
  }

  function ensureSelectedPanel() {
    ensureSelectedSource();
    const ids = availableSourceIds();
    if (isSourcePanel(state.selectedPanel)) {
      const sourceId = panelSourceId(state.selectedPanel);
      if (sourceId && state.ops.sources[sourceId]) {
        state.selectedSourceId = sourceId;
        return;
      }
    }
    if (state.selectedPanel === "sources") {
      state.selectedPanel = state.selectedSourceId ? sourcePanelKey(state.selectedSourceId) : "params";
      return;
    }
    const validPanels = new Set(["params", "basemaps", "themes", "raw", "journal"]);
    if (!validPanels.has(state.selectedPanel)) {
      state.selectedPanel = state.selectedSourceId ? sourcePanelKey(state.selectedSourceId) : "params";
    }
  }

  function sourceKindLabel(kind) {
    const normalized = String(kind || "").trim();
    if (!normalized) return "未设置";
    if (normalized === "db") return "数据库";
    return normalized.toUpperCase();
  }

  function renderSummary() {
    if (!summaryRoot) return;
    const latestEntry = Array.isArray(state.journal?.entries) && state.journal.entries.length
      ? state.journal.entries[state.journal.entries.length - 1]
      : null;
    summaryRoot.innerHTML = `
      <div class="manage-ops-summary-head">
        <div class="manage-ops-summary-title">配置文件</div>
        <button type="button" class="manage-ops-btn" data-ops-refresh-summary>刷新</button>
      </div>
      <div class="manage-ops-summary-counts">
        <span class="manage-ops-summary-chip">${formatCountLabel("source", availableSourceIds().length)}</span>
        <span class="manage-ops-summary-chip">${formatCountLabel("param", Object.keys(state.ops.params).length)}</span>
      </div>
      <div class="manage-ops-summary-boundary">只有这个页面可写；.mei 和其他资源文件都保持只读查看。</div>
      <div class="manage-ops-summary-actions">
        <a class="manage-ops-btn manage-ops-btn-link" href="${editorHref()}">打开 .mei-config.json</a>
      </div>
      <div class="manage-ops-summary-latest-body">${latestEntry
        ? `最近：#${latestEntry.revision || 0} · ${escapeHtml(latestEntry.summary || "ops patch")}`
        : `当前 revision：${state.journalRevision || 0}`}</div>
    `;
    const refreshBtn = summaryRoot.querySelector("[data-ops-refresh-summary]");
    if (refreshBtn) {
      refreshBtn.disabled = state.busy;
      refreshBtn.addEventListener("click", loadOpsConfig);
    }
  }

  function fieldInput(key, label, value, placeholder, type = "text") {
    return `
      <label class="manage-ops-field">
        <span class="manage-ops-field-label">${label}</span>
        <input
          class="manage-ops-field-input"
          type="${type}"
          data-source-field="${key}"
          placeholder="${escapeHtml(placeholder || "")}"
          value="${escapeHtml(String(value ?? ""))}"
        />
      </label>
    `;
  }

  function fieldSelect(key, label, value, options) {
    return `
      <label class="manage-ops-field">
        <span class="manage-ops-field-label">${label}</span>
        <select class="manage-ops-field-input" data-source-field="${key}">
          ${options
            .map(
              (option) =>
                `<option value="${escapeHtml(option)}"${option === value ? " selected" : ""}>${escapeHtml(
                  option,
                )}</option>`,
            )
            .join("")}
        </select>
      </label>
    `;
  }

  function renderConfigNav() {
    const sourceItems = availableSourceIds()
      .map((id) => {
        const source = state.ops.sources[id] || {};
        const active = state.selectedPanel === sourcePanelKey(id);
        const meta = escapeHtml(source.path || source.connection || sourceKindLabel(source.kind || ""));
        return `
          <button
            type="button"
            class="manage-config-nav-item manage-config-nav-item-child${active ? " is-active" : ""}"
            data-config-nav="${escapeHtml(sourcePanelKey(id))}"
            title="${escapeHtml(id)}"
          >
            <span class="manage-config-nav-label">${escapeHtml(id)}</span>
            <span class="manage-config-nav-meta">${meta}</span>
          </button>
        `;
      })
      .join("");
    return `
      <aside class="manage-config-nav">
        <div class="manage-config-nav-group">
          <div class="manage-config-nav-group-head">
            <span class="manage-config-nav-group-title">数据源</span>
            <button type="button" class="manage-ops-btn" data-add-source>新增</button>
          </div>
          <div class="manage-config-nav-list">
            ${sourceItems || '<div class="manage-ops-empty-state">暂无数据源</div>'}
          </div>
        </div>
        <div class="manage-config-nav-group">
          <span class="manage-config-nav-group-title">配置段</span>
          <div class="manage-config-nav-list">
            ${renderNavButton("params", "运行参数", formatCountLabel("项", Object.keys(state.ops.params).length))}
            ${renderNavButton("basemaps", "底图配置", formatCountLabel("项", Object.keys(state.ops.basemaps).length))}
            ${renderNavButton("themes", "主题配置", formatCountLabel("项", Object.keys(state.ops.themes).length))}
            ${renderNavButton("raw", "JSON（ops）", "直接改 JSON")}
            ${renderNavButton("journal", "审计记录", formatCountLabel("rev", state.journalRevision))}
          </div>
        </div>
      </aside>
    `;
  }

  function renderNavButton(key, label, meta) {
    const active = state.selectedPanel === key;
    return `
      <button
        type="button"
        class="manage-config-nav-item${active ? " is-active" : ""}"
        data-config-nav="${escapeHtml(key)}"
      >
        <span class="manage-config-nav-label">${label}</span>
        <span class="manage-config-nav-meta">${escapeHtml(meta)}</span>
      </button>
    `;
  }

  function renderSourceDetail() {
    const id = state.selectedSourceId;
    if (!id || !state.ops.sources[id]) {
      return `
        <div class="manage-ops-empty-state">
          先从左侧数据源树中选择一个条目，或新建数据源。
        </div>
      `;
    }
    const source = state.ops.sources[id] || {};
    const kind = String(source.kind || "xlsx").trim() || "xlsx";
    const isDb = kind === "db";
    const supportsSheet = kind === "xlsx";
    const supportsHeaderRow = kind === "xlsx" || kind === "csv";
    const supportsPreviewRows = !isDb;
    return `
      <div class="manage-config-detail-head">
        <div>
          <div class="manage-config-detail-title">${escapeHtml(id)}</div>
          <div class="manage-config-detail-desc">当前编辑的是 <code>ops.sources.${escapeHtml(
            id,
          )}</code>。先填必需字段，其他字段按需补充。</div>
        </div>
        <button type="button" class="manage-ops-btn" data-remove-source="${escapeHtml(id)}">删除数据源</button>
      </div>
      <div class="manage-ops-detail-sections">
        <section class="manage-ops-subsection">
          <div class="manage-ops-subsection-title">基础字段</div>
          <div class="manage-ops-form-grid">
            ${fieldSelect("kind", "类型", kind, ["xlsx", "csv", "json", "geojson", "db"])}
            ${isDb
              ? fieldInput("connection", "连接串", source.connection || "", "sqlite:///data.db")
              : fieldInput("path", "路径", source.path || "", "upload/data.xlsx")}
            ${supportsSheet ? fieldInput("sheet", "工作表", source.sheet || "", "Sheet1") : ""}
            ${supportsHeaderRow
              ? fieldInput("header_row", "表头行", source.header_row ?? "", "1", "number")
              : ""}
            ${supportsPreviewRows
              ? fieldInput("preview_rows", "预览行数", source.preview_rows ?? "", "1000", "number")
              : ""}
          </div>
        </section>
        <section class="manage-ops-subsection">
          <div class="manage-ops-subsection-title">${isDb ? "数据库选项" : "兼容字段"}</div>
          <div class="manage-ops-form-grid">
            ${isDb
              ? `
                ${fieldInput("table", "数据表", source.table || "", "table_name")}
                ${fieldInput("query", "查询 SQL", source.query || "", "SELECT * FROM ...")}
                ${fieldInput("page_size", "分页大小", source.page_size ?? "", "20", "number")}
                ${fieldInput("max_page_size", "最大分页", source.max_page_size ?? "", "1000", "number")}
                ${fieldInput("path", "可选路径", source.path || "", "sqlite.db")}
              `
              : `
                ${fieldInput("connection", "可选连接串", source.connection || "", "通常留空")}
                ${fieldInput("table", "可选数据表", source.table || "", "通常留空")}
                ${fieldInput("query", "可选查询 SQL", source.query || "", "通常留空")}
              `}
          </div>
        </section>
      </div>
      <div class="manage-ops-field-help">当前类型：${escapeHtml(sourceKindLabel(kind))}。切换类型后，右侧表单会自动切换到对应字段集合。</div>
    `;
  }

  function renderParamRows() {
    if (!state.paramRows.length) {


/* ===== manage-ops-panel/p2.js ===== */
      return '<div class="manage-ops-empty-state">暂无运行参数，点击“新增参数”创建。</div>';
    }
    return state.paramRows
      .map(
        (row) => `
          <div class="manage-ops-param-row" data-param-row="${row.id}">
            <input
              class="manage-ops-field-input"
              type="text"
              data-param-key
              placeholder="参数名"
              value="${escapeHtml(row.key)}"
            />
            <input
              class="manage-ops-field-input"
              type="text"
              data-param-value
              placeholder="参数值（字符串或 JSON）"
              value="${escapeHtml(row.valueText)}"
            />
            <button type="button" class="manage-ops-btn" data-remove-param-row="${row.id}">删除</button>
          </div>
        `,
      )
      .join("");
  }

  function renderParamsPanel() {
    return `
      <div class="manage-config-detail-head">
        <div>
          <div class="manage-config-detail-title">运行参数</div>
          <div class="manage-config-detail-desc">编辑 <code>ops.params</code>。这里适合路径、URL、简单样式值和轻量 JSON。</div>
        </div>
        <button type="button" class="manage-ops-btn" data-add-param-row>新增参数</button>
      </div>
      <div class="manage-ops-params-list">
        ${renderParamRows()}
      </div>
    `;
  }

  function renderJsonPanel(title, desc, dataAttr, text) {
    return `
      <div class="manage-config-detail-head">
        <div>
          <div class="manage-config-detail-title">${title}</div>
          <div class="manage-config-detail-desc">${desc}</div>
        </div>
      </div>
      <textarea class="manage-ops-editor-textarea manage-config-code" data-ops-json="${dataAttr}" spellcheck="false">${escapeHtml(
        text,
      )}</textarea>
    `;
  }

  function renderJournalEntries(limit = 20) {
    const entries = Array.isArray(state.journal?.entries)
      ? state.journal.entries.slice().reverse().slice(0, limit)
      : [];
    if (!entries.length) {
      return '<div class="manage-ops-journal-empty">暂无审计记录</div>';
    }
    return entries
      .map((entry) => {
        const summary = escapeHtml(entry.summary || "ops patch");
        const actor = escapeHtml(entry.actor || "manage");
        return `
          <article class="manage-ops-journal-entry">
            <div class="manage-ops-journal-meta">
              <span>#${entry.revision || 0}</span>
              <span>${actor}</span>
              <span>${formatTimestamp(entry.at_ms)}</span>
            </div>
            <div class="manage-ops-journal-summary">${summary}</div>
          </article>
        `;
      })
      .join("");
  }

  function currentOpsSnapshot() {
    const snapshot = normalizeOps(state.ops);
    snapshot.params = buildParamsObjectFromRows(state.paramRows);
    try {
      snapshot.basemaps = parseJsonObject(state.basemapsText, "底图配置");
    } catch (_) {
      snapshot.basemaps = normalizeOps(state.ops).basemaps;
    }
    try {
      snapshot.themes = parseJsonObject(state.themesText, "主题配置");
    } catch (_) {
      snapshot.themes = normalizeOps(state.ops).themes;
    }
    return snapshot;
  }

  function renderRawPanel() {
    if (!state.rawOpsDirty) {
      state.rawOpsText = stringifyJson(currentOpsSnapshot());
    }
    return `
      <div class="manage-config-detail-head">
        <div>
          <div class="manage-config-detail-title">JSON（ops）</div>
          <div class="manage-config-detail-desc">必要时直接编辑 <code>.mei-config.json</code> 中可写的 <code>ops</code> 段。保存时会以这里的 JSON 为准。</div>
        </div>
      </div>
      <textarea class="manage-ops-editor-textarea manage-config-code manage-config-code-raw" data-ops-json="raw" spellcheck="false">${escapeHtml(
        state.rawOpsText,
      )}</textarea>
    `;
  }

  function renderJournalPanel() {
    return `
      <div class="manage-config-detail-head">
        <div>
          <div class="manage-config-detail-title">审计记录</div>
          <div class="manage-config-detail-desc">所有保存只写 <code>.mei-config.json</code> 与 <code>ops journal</code>。</div>
        </div>
      </div>
      <div class="manage-ops-panel-journal-list">${renderJournalEntries()}</div>
    `;
  }

  function renderActivePanel() {
    if (isSourcePanel(state.selectedPanel)) {
      state.selectedSourceId = panelSourceId(state.selectedPanel);
      return renderSourceDetail();
    }
    if (state.selectedPanel === "params") {
      return renderParamsPanel();
    }
    if (state.selectedPanel === "basemaps") {
      return renderJsonPanel(
        "底图配置",
        "适合保留为 JSON。对应 <code>ops.basemaps</code>，供 <code>basemap_ref(...)</code> 使用。",
        "basemaps",
        state.basemapsText,
      );
    }
    if (state.selectedPanel === "themes") {
      return renderJsonPanel(
        "主题配置",
        "适合保留为 JSON。对应 <code>ops.themes</code>，供 <code>theme_ref(...)</code> 使用。",
        "themes",
        state.themesText,
      );
    }
    if (state.selectedPanel === "journal") {
      return renderJournalPanel();
    }
    return renderRawPanel();
  }

  function renderEditor() {
    if (!editorRoot) return;
    ensureSelectedPanel();
    editorRoot.innerHTML = `
      <div class="manage-config-editor">
        <div class="manage-config-header-note">配置改动只通过这个页面完成；.mei 和其他资源页统一保持只读查看。</div>
        <div class="manage-config-layout">
          ${renderConfigNav()}
          <section class="manage-config-detail">
            ${renderActivePanel()}
          </section>
        </div>
        <div class="manage-ops-savebar">
          <input
            type="text"
            class="manage-ops-summary-input"
            data-ops-summary
            placeholder="变更说明（保存后写入 ops journal）"
            value="${escapeHtml(state.summaryText)}"
          />
          <div class="manage-ops-action-buttons">
            <button type="button" class="manage-ops-btn" data-ops-refresh-main>刷新</button>
            <button type="button" class="manage-ops-btn manage-ops-btn-primary" data-ops-save-main>保存</button>
          </div>
        </div>
      </div>
    `;

    const refreshBtn = editorRoot.querySelector("[data-ops-refresh-main]");
    const saveBtn = editorRoot.querySelector("[data-ops-save-main]");
    const addSourceBtn = editorRoot.querySelector("[data-add-source]");
    const addParamBtn = editorRoot.querySelector("[data-add-param-row]");

    if (refreshBtn) refreshBtn.addEventListener("click", loadOpsConfig);
    if (saveBtn) saveBtn.addEventListener("click", saveOpsConfig);
    if (addSourceBtn) addSourceBtn.addEventListener("click", handleAddSource);
    if (addParamBtn) addParamBtn.addEventListener("click", handleAddParamRow);

    editorRoot.querySelectorAll("[data-config-nav]").forEach((node) => {
      node.addEventListener("click", () => {
        syncEditorDraftsFromDom();
        if (!tryPersistCurrentSourceDetail()) return;
        state.selectedPanel = node.getAttribute("data-config-nav") || "params";
        if (isSourcePanel(state.selectedPanel)) {
          state.selectedSourceId = panelSourceId(state.selectedPanel);
        }
        renderEditor();
      });
    });

    editorRoot.querySelectorAll("input, textarea, select").forEach((node) => {
      node.addEventListener("input", () => {
        if (node.getAttribute("data-ops-json") === "raw") {
          state.rawOpsDirty = true;
        }
        markDirty();
      });
      node.addEventListener("change", () => {
        if (node.getAttribute("data-ops-json") === "raw") {
          state.rawOpsDirty = true;
        }
        markDirty();
      });
    });

    editorRoot.querySelectorAll('[data-source-field="kind"]').forEach((node) => {
      node.addEventListener("change", () => {
        syncEditorDraftsFromDom();
        if (!tryPersistCurrentSourceDetail()) return;
        renderEditor();
      });
    });

    editorRoot.querySelectorAll("[data-remove-source]").forEach((node) => {
      node.addEventListener("click", () => {
        syncEditorDraftsFromDom();
        if (!tryPersistCurrentSourceDetail()) return;
        const sourceId = node.getAttribute("data-remove-source");
        if (!sourceId || !state.ops.sources[sourceId]) return;
        delete state.ops.sources[sourceId];
        ensureSelectedSource();
        state.selectedPanel = state.selectedSourceId ? sourcePanelKey(state.selectedSourceId) : "params";
        markDirty();
        renderAll();
      });
    });

    editorRoot.querySelectorAll("[data-remove-param-row]").forEach((node) => {
      node.addEventListener("click", () => {
        syncEditorDraftsFromDom();
        const rowId = node.getAttribute("data-remove-param-row");
        state.paramRows = state.paramRows.filter((row) => row.id !== rowId);
        markDirty();
        renderEditor();
      });
    });

    setBusy(state.busy);
  }

  function setBusy(busy) {
    state.busy = !!busy;
    [summaryRoot, editorRoot].forEach((root) => {
      if (!root) return;
      root.querySelectorAll("button, input, textarea, select").forEach((node) => {
        node.disabled = state.busy;
      });
    });
  }

  function setEditorStatus(text, tone = "neutral") {
    if (!editorRoot) return;
    const statusEl = editorRoot.querySelector("[data-ops-editor-status]");
    if (!statusEl) return;
    statusEl.textContent = text;
    statusEl.dataset.tone = tone;
  }

  function renderAll() {
    renderSummary();
    renderEditor();
  }

  function parseJsonObject(raw, label) {
    const trimmed = String(raw || "").trim();
    if (!trimmed) return {};
    let parsed;
    try {
      parsed = JSON.parse(trimmed);
    } catch (error) {
      throw new Error(`${label} 解析失败：${error.message || error}`);
    }
    if (!isPlainObject(parsed)) {
      throw new Error(`${label} 必须是 JSON 对象`);
    }
    return parsed;
  }

  function parseLooseValue(raw) {
    const trimmed = String(raw || "").trim();
    if (!trimmed) return "";
    if (
      trimmed.startsWith("{") ||
      trimmed.startsWith("[") ||
      trimmed === "true" ||
      trimmed === "false" ||
      trimmed === "null" ||
      trimmed.startsWith('"') ||
      /^-?\d+(\.\d+)?$/.test(trimmed)
    ) {
      try {
        return JSON.parse(trimmed);
      } catch (_error) {
        return trimmed;
      }
    }
    return trimmed;
  }

  function buildParamsObjectFromRows(rows) {
    const params = {};
    for (const row of rows || []) {
      const key = String(row.key || "").trim();
      if (!key) continue;
      params[key] = parseLooseValue(row.valueText);
    }
    return params;
  }

  function syncParamRowsFromDom() {
    if (!editorRoot) return;
    const rows = [];
    editorRoot.querySelectorAll("[data-param-row]").forEach((rowEl) => {
      rows.push({
        id: rowEl.getAttribute("data-param-row") || nextParamRowId(),
        key: String(rowEl.querySelector("[data-param-key]")?.value || ""),
        valueText: String(rowEl.querySelector("[data-param-value]")?.value || ""),
      });
    });
    state.paramRows = rows;
  }

  function syncSummaryFromDom() {
    if (!editorRoot) return;
    state.summaryText = String(editorRoot.querySelector("[data-ops-summary]")?.value || "");
  }

  function syncJsonDraftsFromDom() {
    if (!editorRoot) return;


/* ===== manage-ops-panel/p3.js ===== */
    const basemapsEl = editorRoot.querySelector('[data-ops-json="basemaps"]');
    const themesEl = editorRoot.querySelector('[data-ops-json="themes"]');
    const rawEl = editorRoot.querySelector('[data-ops-json="raw"]');
    if (basemapsEl) state.basemapsText = String(basemapsEl.value || "");
    if (themesEl) state.themesText = String(themesEl.value || "");
    if (rawEl) state.rawOpsText = String(rawEl.value || "");
  }

  function syncEditorDraftsFromDom() {
    syncSummaryFromDom();
    syncParamRowsFromDom();
    syncJsonDraftsFromDom();
  }

  function markDirty() {
    state.isDirty = true;
    setEditorStatus("有未保存更改", "warn");
  }

  function buildParamsObject() {
    syncParamRowsFromDom();
    return buildParamsObjectFromRows(state.paramRows);
  }

  function parseOptionalInteger(raw, label) {
    const trimmed = String(raw || "").trim();
    if (!trimmed) return undefined;
    const value = Number(trimmed);
    if (!Number.isFinite(value) || value < 0) {
      throw new Error(`${label} 必须是非负数字`);
    }
    return Math.trunc(value);
  }

  function persistCurrentSourceDetailFromDom() {
    if (!editorRoot || !state.selectedSourceId || !state.ops.sources[state.selectedSourceId]) return;
    if (!isSourcePanel(state.selectedPanel)) return;
    const next = {};
    const fields = ["kind", "path", "connection", "sheet", "table", "query"];
    fields.forEach((key) => {
      const value = String(editorRoot.querySelector(`[data-source-field="${key}"]`)?.value || "").trim();
      if (value) next[key] = value;
    });
    const integerFields = [
      ["header_row", "表头行"],
      ["preview_rows", "预览行数"],
      ["page_size", "分页大小"],
      ["max_page_size", "最大分页"],
    ];
    for (const [field, label] of integerFields) {
      const raw = editorRoot.querySelector(`[data-source-field="${field}"]`)?.value;
      const value = parseOptionalInteger(raw, label);
      if (value !== undefined) next[field] = value;
    }
    state.ops.sources[state.selectedSourceId] = next;
    state.rawOpsDirty = false;
  }

  function tryPersistCurrentSourceDetail() {
    try {
      persistCurrentSourceDetailFromDom();
      return true;
    } catch (error) {
      setEditorStatus(String(error?.message || error), "danger");
      return false;
    }
  }

  function validateSources(sources) {
    for (const [id, source] of Object.entries(sources)) {
      if (!isPlainObject(source)) {
        throw new Error(`数据源 ${id} 必须是对象`);
      }
      const kind = String(source.kind || "").trim();
      if (!kind) {
        throw new Error(`数据源 ${id} 缺少 kind`);
      }
      if (kind === "db") {
        if (!String(source.connection || source.path || "").trim()) {
          throw new Error(`数据库数据源 ${id} 需填写 connection 或 path`);
        }
      } else if (!String(source.path || "").trim()) {
        throw new Error(`数据源 ${id} 缺少 path`);
      }
    }
  }

  async function fetchJson(url, options = undefined) {
    const response = await fetch(url, {
      credentials: "same-origin",
      ...options,
    });
    const payload = await response.json().catch(() => ({}));
    if (!response.ok) {
      throw new Error(payload.error || payload.message || `HTTP ${response.status}`);
    }
    return payload;
  }

  const SHELL_THEME_VAR_PREFIX = /^--mei-(shell|chrome)-/;

  function isSceneThemeCssVar(name) {
    return String(name || "").startsWith("--mei-") && !SHELL_THEME_VAR_PREFIX.test(name);
  }

  function parseInlineStyleMap(styleText) {
    const map = new Map();
    for (const chunk of String(styleText || "").split(";")) {
      const part = chunk.trim();
      if (!part) continue;
      const idx = part.indexOf(":");
      if (idx <= 0) continue;
      const key = part.slice(0, idx).trim();
      const value = part.slice(idx + 1).trim();
      if (key) map.set(key, value);
    }
    return map;
  }

  function mergeSceneThemeInlineStyle(existingStyle, sceneVarStyle) {
    const merged = parseInlineStyleMap(existingStyle);
    for (const key of [...merged.keys()]) {
      if (isSceneThemeCssVar(key)) {
        merged.delete(key);
      }
    }
    for (const [key, value] of parseInlineStyleMap(sceneVarStyle)) {
      if (isSceneThemeCssVar(key)) {
        merged.set(key, value);
      }
    }
    return Array.from(merged.entries())
      .map(([key, value]) => `${key}: ${value}`)
      .join("; ");
  }

  function patchSceneThemeStyleInDocument(doc, cssVarsStyle) {
    if (!doc || !cssVarsStyle?.trim()) return false;
    const style = cssVarsStyle.trim();
    let patched = false;
    doc.querySelectorAll(".preview-viewport").forEach((node) => {
      node.setAttribute(
        "style",
        mergeSceneThemeInlineStyle(node.getAttribute("style") || "", style),
      );
      patched = true;
    });
    const body = doc.body;
    if (body) {
      body.setAttribute(
        "style",
        mergeSceneThemeInlineStyle(body.getAttribute("style") || "", style),
      );
      patched = true;
    }
    return patched;
  }

  function notifyPreviewThemeUpdated(targetWindow) {
    const view = targetWindow || window;
    try {
      view.dispatchEvent(
        new CustomEvent("meilang:preview-updated", {
          bubbles: true,
          detail: { reason: "ops-theme-overlay", resetRuntimeQueryCache: false },
        }),
      );
    } catch {
      /* ignore cross-origin opener */
    }
  }

  function resolveSceneQueryFromLocation(loc) {
    try {
      const params = new URLSearchParams(loc?.search || "");
      const scene = params.get("scene") || params.get("sceneId") || "";
      return scene.trim();
    } catch {
      return "";
    }
  }

  async function applySceneThemeOverlayHot(targetWindow) {
    if (!state.appId) return;
    const scene = resolveSceneQueryFromLocation(targetWindow?.location || window.location);
    const query = scene ? `?scene=${encodeURIComponent(scene)}` : "";
    const payload = await fetchJson(
      `/api/ops/theme/style/${encodeURIComponent(state.appId)}${query}`,
    );
    if (patchSceneThemeStyleInDocument(targetWindow.document, payload.css_vars_style || "")) {
      notifyPreviewThemeUpdated(targetWindow);
    }
  }

  async function broadcastSceneThemeOverlayHot() {
    const targets = [window];
    if (window.opener && !window.opener.closed) {
      targets.push(window.opener);
    }
    const seen = new Set();
    for (const target of targets) {
      if (!target || seen.has(target)) continue;
      seen.add(target);
      try {
        await applySceneThemeOverlayHot(target);
      } catch {
        /* non-fatal: preview may be closed or artifact missing */
      }
    }
  }

  async function loadOpsConfig() {
    setBusy(true);
    try {
      const [configPayload, boundaryPayload, journalPayload] = await Promise.all([
        fetchJson(`/api/ops/config/${encodeURIComponent(state.appId)}`),
        fetchJson("/api/ops/boundary"),
        fetchJson(`/api/ops/journal/${encodeURIComponent(state.appId)}`),
      ]);
      state.journalRevision = configPayload.journal_revision || 0;
      state.boundary = boundaryPayload;
      state.ops = normalizeOps(configPayload.config?.ops || {});
      state.journal = journalPayload.journal || { entries: [] };
      state.paramRows = hydrateParamRows(state.ops.params);
      state.basemapsText = stringifyJson(state.ops.basemaps);
      state.themesText = stringifyJson(state.ops.themes);
      state.rawOpsText = stringifyJson(state.ops);
      state.rawOpsDirty = false;
      state.isDirty = false;
      ensureSelectedPanel();
      renderAll();
      setEditorStatus(`rev ${state.journalRevision || 0}`, "good");
    } catch (error) {
      renderSummary();
      if (editorRoot) {
        editorRoot.innerHTML = `<div class="manage-config-editor"><div class="manage-ops-empty-state">${escapeHtml(
          String(error?.message || error),
        )}</div></div>`;
      }
    } finally {
      setBusy(false);
    }
  }

  function handleAddParamRow() {
    syncEditorDraftsFromDom();
    if (!tryPersistCurrentSourceDetail()) return;
    state.paramRows.push({
      id: nextParamRowId(),
      key: "",
      valueText: "",
    });
    state.selectedPanel = "params";
    state.rawOpsDirty = false;
    markDirty();
    renderEditor();
  }

  function handleAddSource() {
    syncEditorDraftsFromDom();
    if (!tryPersistCurrentSourceDetail()) return;
    let nextId = "new_source";
    let index = 1;
    while (state.ops.sources[nextId]) {
      nextId = `new_source_${index}`;
      index += 1;
    }
    state.ops.sources[nextId] = {
      kind: "xlsx",
      path: "",
    };
    state.selectedSourceId = nextId;
    state.selectedPanel = sourcePanelKey(nextId);
    state.rawOpsDirty = false;
    markDirty();
    renderAll();
  }

  function applyRawOpsDraft() {
    const nextOps = normalizeOps(parseJsonObject(state.rawOpsText, "JSON（ops）"));
    state.ops = nextOps;
    state.paramRows = hydrateParamRows(nextOps.params);
    state.basemapsText = stringifyJson(nextOps.basemaps);
    state.themesText = stringifyJson(nextOps.themes);
    state.rawOpsText = stringifyJson(nextOps);
    state.rawOpsDirty = false;
    ensureSelectedPanel();
  }

  async function saveOpsConfig() {
    try {
      syncEditorDraftsFromDom();
      if (state.rawOpsDirty) {
        applyRawOpsDraft();
      }
      if (!tryPersistCurrentSourceDetail()) return;
      const params = buildParamsObject();
      const basemaps = parseJsonObject(state.basemapsText, "底图配置");
      const themes = parseJsonObject(state.themesText, "主题配置");
      validateSources(state.ops.sources);
      setBusy(true);
      setEditorStatus("保存中…");
      syncSummaryFromDom();
      const summary = state.summaryText.trim();
      const payload = await fetchJson(`/api/ops/config/${encodeURIComponent(state.appId)}`, {
        method: "PUT",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          actor: "manage-ui",
          summary,
          patch: {
            params,
            basemaps,
            themes,
            sources: state.ops.sources,
          },
        }),
      });
      state.summaryText = "";
      state.journalRevision = payload.revision || state.journalRevision;
      await loadOpsConfig();
      await broadcastSceneThemeOverlayHot();
      const usesUploadPath = Object.values(state.ops.sources || {}).some((source) => {
        const path = String(source?.path || "").trim();
        return path.startsWith("upload/") && /\.xlsx$/i.test(path);
      });
      if (usesUploadPath) {
        setEditorStatus(
          "已保存。若引用 upload/*.xlsx，请在 Runtime 执行 prebuild 刷新数据链。",
          "good",
        );
      }
    } catch (error) {
      setEditorStatus(`保存失败：${String(error?.message || error)}`, "danger");
      setBusy(false);
    }
  }

  function mountIfPresent() {
    if (!resolveRoots()) return;
    renderSummary();
    if (editorRoot) {
      editorRoot.innerHTML = '<div class="manage-config-editor"><div class="manage-ops-empty-state">加载中…</div></div>';
    }
    loadOpsConfig();
  }

  document.addEventListener("mei:manage-context-change", () => {
    window.setTimeout(mountIfPresent, 0);
  });

  mountIfPresent();
})();


/* ===== manage-ops-panel/p4.js ===== */
(function initManageOpsLayoutTuningOverlay() {
  const global = window;

  function notifyLayoutTuningOverlay(reason) {
    try {
      global.dispatchEvent(
        new CustomEvent("meilang:preview-updated", {
          bubbles: true,
          detail: { reason: reason || "layout-tuning-overlay", resetRuntimeQueryCache: false },
        }),
      );
    } catch (_) {}
  }

  function ensureDraftSessionId() {
    const cookieKey = "mei-draft-session";
    const match = String(document.cookie || "").match(/mei-draft-session=([^;]+)/);
    if (match && match[1]) return decodeURIComponent(match[1].trim());
    const id = `web-${Date.now()}-${Math.random().toString(36).slice(2, 10)}`;
    document.cookie = `${cookieKey}=${encodeURIComponent(id)};path=/;SameSite=Lax`;
    return id;
  }

  function draftSessionHeaders() {
    return { "x-mei-draft-session": ensureDraftSessionId() };
  }

  async function fetchOverlay(appId) {
    const resp = await fetch(
      `/api/ops/layout-tuning/overlay/${encodeURIComponent(appId)}`,
      {
        credentials: "same-origin",
        headers: { Accept: "application/json", ...draftSessionHeaders() },
      },
    );
    if (!resp.ok) throw new Error(`layoutTuning overlay failed: ${resp.status}`);
    return resp.json();
  }

  function applyContentBudgetToNode(node, budget) {
    if (!(node instanceof HTMLElement) || !budget || typeof budget !== "object") return false;
    let patched = false;
    const rows = budget.rows ?? budget.content_rows ?? budget.contentRows;
    const gap = budget.gap ?? budget.content_gap ?? budget.contentGap;
    if (Array.isArray(rows) && rows.length > 0) {
      const total = rows.reduce((sum, row) => sum + Number(row), 0);
      if (total > 0) {
        node.style.gridTemplateRows = rows
          .map((row) => `${(Number(row) / total) * 100}fr`)
          .join(" ");
      } else {
        node.style.gridTemplateRows = rows.map((row) => `${row}px`).join(" ");
      }
      node.dataset.layoutTuningContentRows = rows.join(",");
      patched = true;
    }
    if (gap != null && gap !== "") {
      node.style.rowGap = `${gap}px`;
      node.dataset.layoutTuningContentGap = String(gap);
      patched = true;
    }
    return patched;
  }

  function applyOverlayEntries(root, entries) {
    if (!(root instanceof HTMLElement) || !entries || typeof entries !== "object") return false;
    let patched = false;
    Object.entries(entries).forEach(([scope, patch]) => {
      if (!patch || typeof patch !== "object") return;
      const selector = `[data-preview-scope="${CSS.escape(scope)}"]`;
      const node = root.querySelector(selector);
      if (!(node instanceof HTMLElement)) return;
      const slotHeight =
        patch.slotHeight ?? patch.slot_height ?? patch.card_height ?? patch.cardHeight;
      if (slotHeight != null) {
        node.style.setProperty("--mei-slot-height", `${slotHeight}px`);
        node.dataset.layoutTuningSlotHeight = String(slotHeight);
        patched = true;
      }
      const paddingProfile = patch.paddingProfile ?? patch.padding_profile;
      if (paddingProfile) {
        node.dataset.layoutTuningPaddingProfile = String(paddingProfile);
        patched = true;
      }
      const contentBudget = patch.content_budget ?? patch.contentBudget;
      if (applyContentBudgetToNode(node, contentBudget)) {
        patched = true;
      }
    });
    return patched;
  }

  async function applyLayoutTuningOverlayHot(appId, targetWindow) {
    const view = targetWindow || global;
    const payload = await fetchOverlay(appId);
    const root =
      view.document.querySelector(".preview-pane-scroll") ||
      view.document.querySelector(".preview-pane");
    const boot = view.__meiLangBoot || global.__meiLangBoot || {};
    if (boot.viewCompositor?.applyThemeAndOverlay) {
      boot.viewCompositor.applyThemeAndOverlay(root, null, {
        patches: payload.entries || {},
      });
      notifyLayoutTuningOverlay(payload.draft_active ? "layout-tuning-draft" : "layout-tuning-overlay");
      return;
    }
    if (applyOverlayEntries(root, payload.entries || {})) {
      notifyLayoutTuningOverlay(payload.draft_active ? "layout-tuning-draft" : "layout-tuning-overlay");
      if (typeof view.MeiFrameStageBoot?.scheduleFrameViewportRelayout === "function") {
        try {
          view.MeiFrameStageBoot.scheduleFrameViewportRelayout();
        } catch (_) {}
      }
    }
  }

  async function putSessionDraft(appId, tuning) {
    const resp = await fetch(
      `/api/ops/layout-tuning/draft/${encodeURIComponent(appId)}`,
      {
        method: "PUT",
        credentials: "same-origin",
        headers: {
          "Content-Type": "application/json",
          Accept: "application/json",
          ...draftSessionHeaders(),
        },
        body: JSON.stringify({ tuning }),
      },
    );
    if (!resp.ok) throw new Error(`layoutTuning draft failed: ${resp.status}`);
    return resp.json();
  }

  async function applyDraftToConfig(appId) {
    const resp = await fetch(
      `/api/ops/layout-tuning/apply/${encodeURIComponent(appId)}`,
      {
        method: "POST",
        credentials: "same-origin",
        headers: {
          Accept: "application/json",
          ...draftSessionHeaders(),
        },
      },
    );
    if (!resp.ok) throw new Error(`layoutTuning apply failed: ${resp.status}`);
    const payload = await resp.json();
    notifyLayoutTuningOverlay("layout-tuning-persisted");
    return payload;
  }

  global.MeiOpsLayoutTuningOverlay = {
    applyHot: applyLayoutTuningOverlayHot,
    putSessionDraft,
    applyDraftToConfig,
    fetchOverlay,
    notify: notifyLayoutTuningOverlay,
  };
})();

